		50735893&2021-05-12 10:32:00,
		50736733&2021-05-12 14:15:00,
		50737080&2021-05-12 11:08:00,
		50738102&2021-05-12 13:48:00,
		50739206&2021-05-12 13:33:00,
		50739643&2021-05-12 12:56:00,
		50739760&2021-05-12 11:22:00,
		50740045&2021-05-12 12:35:00,
		50740129&2021-05-12 13:07:00,
		50740492&2021-05-12 13:54:00,
		50742091&2021-05-12 13:43:00,
		50742558&2021-05-12 14:09:00,
		50742571&2021-05-12 14:15:00,
		50743496&2021-05-12 19:21:00,
		50743751&2021-05-12 16:18:00,
		50743878&2021-05-12 14:24:00,
		50744113&2021-05-12 14:57:00,
		50744239&2021-05-12 18:13:00,
		50744284&2021-05-12 16:48:00'
	
	SELECT REPLACE (REPLACE(REPLACE(val,char(9),''),char(13),''),char(10),'') custid
	INTO #tmpCust
	FROM dbo.f_SplitString(@string, ',')
	OPTION (MAXRECURSION 0)	
	
	;WITH t AS (
		SELECT (SELECT val FROM dbo.strSplit(custid,'&') where rank = 1) as custid,
				(SELECT val FROM dbo.strSplit(custid,'&') where rank = 2) as markdate				
		FROM #tmpCust
	)
	INSERT INTO ProblemAccountClassification(custid,IsReviewed,ModifiedDate)
	SELECT t.custid, 0, Markdate
	FROM t
		INNER JOIN custinfo ci WITH(NOLOCK) ON t.custid = ci.custid
	WHERE NOT EXISTS (SELECT 1 FROM ProblemAccountClassification pc WITH(NOLOCK) WHERE pc.custid = t.custid)
		AND ci.customerClass IN (8,9,10,11,13)
		
		
	DROP TABLE #tmpCust
END	
